<?php require __DIR__.'/config.php';require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY id DESC");$s->execute([current_user()['id']]);$orders=$s->fetchAll();$pageTitle='Your orders';require __DIR__.'/includes/header.php';?><h1 class="page-title">Your orders</h1><?php if(isset($_GET['placed'])): ?><div class="notice">Your order has been placed successfully.</div><?php endif; ?><?php if(!$orders): ?><div class="empty"><h2>No orders yet</h2><a class="btn" href="<?= url() ?>">Start shopping</a></div><?php endif; ?><?php foreach($orders as $o): ?><article class="order-card"><div><small>ORDER #<?= $o['id'] ?> · <?= h($o['created_at']) ?></small><h3><?= money($o['total']) ?></h3><p><?= h($o['customer_name']) ?> · <?= h($o['phone']) ?></p><p><?= h($o['address']) ?></p></div><span class="status"><?= h($o['status']) ?></span></article><?php endforeach; ?><?php require __DIR__.'/includes/footer.php';?>
